{"content": "     1|<!DOCTYPE html>
     2|<html lang="en">
     3|<head>
     4|<meta charset="UTF-8">
     5|<meta name="viewport" content="width=device-width, initial-scale=1.0">
     6|<title>MIFECO Content Command Center</title>
     7|<link rel="preconnect" href="https://fonts.googleapis.com">
     8|<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
     9|<style>
    10|:root {
    11|  --bg: #0f172a;
    12|  --card-bg: #1e293b;
    13|  --accent: #00ffcc;
    14|  --secondary: #667eea;
    15|  --text: #e2e8f0;
    16|  --text-muted: #94a3b8;
    17|  --border: #334155;
    18|  --danger: #ef4444;
    19|  --success: #22c55e;
    20|  --warning: #f59e0b;
    21|}
    22|*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
    23|html{font-size:16px}
    24|body{font-family:'Inter',-apple-system,sans-serif;background:var(--bg);color:var(--text);display:flex;min-height:100vh;overflow-x:hidden}
    25|a{color:var(--accent);text-decoration:none}
    26|a:hover{text-decoration:underline}
    27|
    28|/* Sidebar */
    29|.sidebar{position:fixed;left:0;top:0;bottom:0;width:220px;background:#0c1225;border-right:1px solid var(--border);display:flex;flex-direction:column;z-index:100;transition:transform .3s ease}
    30|.sidebar-logo{padding:24px 20px 16px;border-bottom:1px solid var(--border)}
    31|.sidebar-logo .logo-icon{width:36px;height:36px;background:var(--accent);border-radius:8px;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:18px;color:#0f172a;margin-bottom:8px}
    32|.sidebar-logo h2{font-size:15px;font-weight:700;color:var(--text);letter-spacing:-.3px}
    33|.sidebar-logo p{font-size:10px;color:var(--accent);text-transform:uppercase;letter-spacing:1.5px;font-weight:600;margin-top:2px}
    34|.sidebar-stats{padding:20px;border-bottom:1px solid var(--border);display:flex;flex-direction:column;gap:12px}
    35|.stat-item{display:flex;justify-content:space-between;align-items:center}
    36|.stat-label{font-size:12px;color:var(--text-muted)}
    37|.stat-value{font-size:16px;font-weight:700;color:var(--text)}
    38|.stat-value.accent{color:var(--accent)}
    39|.stat-value.success{color:var(--success)}
    40|.stat-value.secondary{color:var(--secondary)}
    41|.sidebar-nav{padding:16px 0;flex:1}
    42|.sidebar-nav a{display:flex;align-items:center;gap:10px;padding:10px 20px;font-size:13px;color:var(--text-muted);transition:all .15s}
    43|.sidebar-nav a:hover{color:var(--text);background:rgba(255,255,255,.04);text-decoration:none}
    44|.sidebar-nav a .nav-icon{width:18px;text-align:center;font-size:15px}
    45|.sidebar-nav a.active{color:var(--accent);border-left:2px solid var(--accent);background:rgba(0,255,204,.06)}
    46|
    47|/* Main */
    48|.main{padding-left:220px;width:100%;min-height:100vh;display:flex;flex-direction:column}
    49|
    50|/* Header */
    51|.header{padding:24px 32px 16px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:flex-start}
    52|.header-left h1{font-size:22px;font-weight:800;letter-spacing:-.5px;color:var(--text)}
    53|.header-left p{font-size:13px;color:var(--text-muted);margin-top:4px}
    54|.header-right{display:flex;gap:12px;align-items:center}
    55|.hamburger{display:none;background:none;border:none;color:var(--text);font-size:24px;cursor:pointer;padding:4px}
    56|.mobile-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:99}
    57|
    58|/* Tabs */
    59|.tabs{display:flex;border-bottom:1px solid var(--border);padding:0 32px;overflow-x:auto;scrollbar-width:none;gap:0}
    60|.tabs::-webkit-scrollbar{display:none}
    61|.tab-btn{background:none;border:none;color:var(--text-muted);padding:14px 20px;font-size:13px;font-weight:500;cursor:pointer;position:relative;white-space:nowrap;transition:color .15s;font-family:'Inter',sans-serif}
    62|.tab-btn:hover{color:var(--text)}
    63|.tab-btn.active{color:var(--accent)}
    64|.tab-btn.active::after{content:'';position:absolute;bottom:0;left:8px;right:8px;height:2px;background:var(--accent);border-radius:2px}
    65|.tab-badge{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 5px;border-radius:9px;background:var(--secondary);color:#fff;font-size:10px;font-weight:700;margin-left:6px;vertical-align:middle}
    66|
    67|/* Content */
    68|.content-area{flex:1;padding:24px 32px}
    69|.viewer{display:none}
    70|.viewer.active{display:block}
    71|
    72|/* Search */
    73|.search-bar{position:relative;margin-bottom:20px}
    74|.search-bar input{width:100%;padding:10px 16px 10px 40px;background:var(--card-bg);border:1px solid var(--border);border-radius:8px;color:var(--text);font-size:13px;font-family:'Inter',sans-serif;outline:none;transition:border .15s}
    75|.search-bar input:focus{border-color:var(--accent)}
    76|.search-bar input::placeholder{color:var(--text-muted)}
    77|.search-bar .search-icon{position:absolute;left:14px;top:50%;transform:translateY(-50%);color:var(--text-muted);font-size:15px;pointer-events:none}
    78|
    79|/* Cards */
    80|.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:16px}
    81|.card{background:var(--card-bg);border:1px solid var(--border);border-radius:10px;padding:18px;transition:all .3s ease;position:relative;overflow:hidden}
    82|.card.sent{border-color:var(--success) !important;background:rgba(34,197,94,.04)}
    83|.card.deleting{transform:translateX(120%);opacity:0;max-height:0;padding:0;margin:0;border-width:0;overflow:hidden;transition:all .4s ease}
    84|.card .sent-overlay{display:none;position:absolute;top:8px;right:8px;background:var(--success);color:#fff;font-size:10px;font-weight:700;padding:3px 8px;border-radius:4px;letter-spacing:.3px}
    85|.card.sent .sent-overlay{display:block}
    86|.card .badge{display:inline-block;font-size:10px;font-weight:600;padding:3px 8px;border-radius:4px;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px}
    87|.badge-saas{background:rgba(102,126,234,.2);color:var(--secondary)}
    88|.badge-consulting{background:rgba(245,158,11,.2);color:var(--warning)}
    89|.badge-books{background:rgba(0,255,204,.15);color:var(--accent)}
    90|.badge-testcorp{background:rgba(239,68,68,.15);color:var(--danger)}
    91|.badge-hypatia{background:rgba(102,126,234,.2);color:var(--secondary)}
    92|.badge-pma{background:rgba(0,255,204,.15);color:var(--accent)}
    93|.badge-vibra{background:rgba(245,158,11,.2);color:var(--warning)}
    94|.badge-consult{background:rgba(239,68,68,.15);color:var(--danger)}
    95|.badge-linkedin{background:rgba(10,102,194,.2);color:#0a66c2}
    96|.badge-x{background:rgba(0,0,0,.3);color:#e2e8f0}
    97|.card h3{font-size:14px;font-weight:600;color:var(--text);line-height:1.4;margin-bottom:6px}
    98|.card .meta{font-size:11px;color:var(--text-muted);margin-bottom:8px;display:flex;flex-wrap:wrap;gap:6px}
    99|.card .body-preview{font-size:12.5px;color:var(--text-muted);line-height:1.6;margin-bottom:10px;max-height:72px;overflow:hidden;transition:max-height .3s ease;position:relative}
   100|.card .body-preview.expanded{max-height:2000px}
   101|.card .body-preview .placeholder{background:rgba(0,255,204,.1);color:var(--accent);padding:1px 4px;border-radius:3px;font-weight:500;font-size:11px}
   102|.card .expand-btn{background:none;border:none;color:var(--accent);font-size:11px;cursor:pointer;padding:0;font-family:'Inter',sans-serif;font-weight:500}
   103|.card .expand-btn:hover{text-decoration:underline}
   104|.card .keywords{display:flex;flex-wrap:wrap;gap:4px;margin-bottom:12px}
   105|.card .keyword{font-size:10px;background:rgba(102,126,234,.1);color:var(--secondary);padding:2px 6px;border-radius:3px}
   106|.card .actions{display:flex;gap:8px;margin-top:0}
   107|.btn{font-family:'Inter',sans-serif;font-size:12px;font-weight:600;padding:7px 16px;border-radius:6px;border:none;cursor:pointer;transition:all .15s;display:inline-flex;align-items:center;gap:5px}
   108|.btn-send{background:var(--accent);color:#0f172a}
   109|.btn-send:hover{background:#00e6b8;transform:translateY(-1px)}
   110|.btn-send:disabled{opacity:.4;cursor:not-allowed;transform:none}
   111|.btn-delete{background:transparent;border:1px solid var(--danger);color:var(--danger)}
   112|.btn-delete:hover{background:var(--danger);color:#fff}
   113|.btn-cancel{background:var(--border);color:var(--text)}
   114|.btn-cancel:hover{background:#3b4f6b}
   115|
   116|/* Modal */
   117|.modal-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:200;align-items:center;justify-content:center}
   118|.modal-overlay.show{display:flex}
   119|.modal{background:var(--card-bg);border:1px solid var(--border);border-radius:12px;padding:28px;max-width:420px;width:90%;text-align:center}
   120|.modal h3{font-size:17px;font-weight:700;margin-bottom:8px}
   121|.modal p{font-size:13px;color:var(--text-muted);margin-bottom:20px;line-height:1.5}
   122|.modal .modal-actions{display:flex;gap:10px;justify-content:center}
   123|
   124|/* Empty state */
   125|.empty-state{text-align:center;padding:60px 20px;color:var(--text-muted)}
   126|.empty-state .empty-icon{font-size:48px;margin-bottom:12px;opacity:.5}
   127|.empty-state h3{font-size:16px;color:var(--text);margin-bottom:6px}
   128|.empty-state p{font-size:13px;max-width:400px;margin:0 auto;line-height:1.6}
   129|
   130|/* Responsive */
   131|@media(max-width:768px){
   132|  .sidebar{transform:translateX(-100%)}
   133|  .sidebar.open{transform:translateX(0)}
   134|  .mobile-overlay.show{display:block}
   135|  .main{padding-left:0}
   136|  .header{padding:16px;flex-direction:column;gap:8px}
   137|  .header-right{width:100%;justify-content:flex-start}
   138|  .hamburger{display:block}
   139|  .tabs{padding:0 12px}
   140|  .tab-btn{padding:12px 14px;font-size:12px}
   141|  .content-area{padding:16px}
   142|  .card-grid{grid-template-columns:1fr}
   143|}
   144|@media(max-width:480px){
   145|  .card-grid{grid-template-columns:1fr}
   146|}
   147|</style>
   148|</head>
   149|<body>
   150|
   151|<div class="mobile-overlay" id="mobileOverlay"></div>
   152|
   153|<!-- Sidebar -->
   154|<aside class="sidebar" id="sidebar">
   155|  <div class="sidebar-logo">
   156|    <div class="logo-icon">M</div>
   157|    <h2>MIFECO</h2>
   158|    <p>Command Center</p>
   159|  </div>
   160|  <div class="sidebar-stats">
   161|    <div class="stat-item"><span class="stat-label">Total Items</span><span class="stat-value" id="statTotal">0</span></div>
   162|    <div class="stat-item"><span class="stat-label">Sent</span><span class="stat-value success" id="statSent">0</span></div>
   163|    <div class="stat-item"><span class="stat-label">Queued</span><span class="stat-value accent" id="statQueued">0</span></div>
   164|  </div>
   165|  <nav class="sidebar-nav">
   166|    <a href="#" class="active"><span class="nav-icon">📊</span> Content Dashboard</a>
   167|    <a href="#"><span class="nav-icon">🔁</span> Pipeline Dashboard</a>
   168|    <a href="#"><span class="nav-icon">🏢</span> Consulting Dashboard</a>
   169|  </nav>
   170|</aside>
   171|
   172|<!-- Main -->
   173|<div class="main">
   174|
   175|  <!-- Header -->
   176|  <header class="header">
   177|    <div class="header-left">
   178|      <button class="hamburger" id="hamburger">☰</button>
   179|      <h1>MIFECO Content Command Center</h1>
   180|      <p>Schedule, review, and deploy content across all channels</p>
   181|    </div>
   182|    <div class="header-right">
   183|      <span style="font-size:12px;color:var(--text-muted)">v1.0</span>
   184|    </div>
   185|  </header>
   186|
   187|  <!-- Tabs -->
   188|  <nav class="tabs" id="tabNav">
   189|    <button class="tab-btn active" data-tab="linkedin-msgs">LinkedIn Messages <span class="tab-badge" id="badge-linkedin-msgs">0</span></button>
   190|    <button class="tab-btn" data-tab="emails">Emails <span class="tab-badge" id="badge-emails">0</span></button>
   191|    <button class="tab-btn" data-tab="x-posts">X Posts <span class="tab-badge" id="badge-x-posts">0</span></button>
   192|    <button class="tab-btn" data-tab="blog-posts">Blog Posts <span class="tab-badge" id="badge-blog-posts">0</span></button>
   193|    <button class="tab-btn" data-tab="linkedin-posts">LinkedIn Posts <span class="tab-badge" id="badge-linkedin-posts">0</span></button>
   194|  </nav>
   195|
   196|  <!-- Content -->
   197|  <div class="content-area">
   198|
   199|    <!-- VIEWER: LinkedIn Messages -->
   200|    <div class="viewer active" id="viewer-linkedin-msgs">
   201|      <div class="search-bar"><span class="search-icon">🔍</span><input type="text" class="filter-input" data-viewer="linkedin-msgs" placeholder="Search LinkedIn messages..."></div>
   202|      <div class="card-grid" id="grid-linkedin-msgs"></div>
   203|    </div>
   204|
   205|    <!-- VIEWER: Emails -->
   206|    <div class="viewer" id="viewer-emails">
   207|      <div class="search-bar"><span class="search-icon">🔍</span><input type="text" class="filter-input" data-viewer="emails" placeholder="Search emails..."></div>
   208|      <div class="card-grid" id="grid-emails"></div>
   209|    </div>
   210|
   211|    <!-- VIEWER: X Posts -->
   212|    <div class="viewer" id="viewer-x-posts">
   213|      <div class="search-bar"><span class="search-icon">🔍</span><input type="text" class="filter-input" data-viewer="x-posts" placeholder="Search X posts..."></div>
   214|      <div class="card-grid" id="grid-x-posts"></div>
   215|    </div>
   216|
   217|    <!-- VIEWER: Blog Posts -->
   218|    <div class="viewer" id="viewer-blog-posts">
   219|      <div class="search-bar"><span class="search-icon">🔍</span><input type="text" class="filter-input" data-viewer="blog-posts" placeholder="Search blog posts..."></div>
   220|      <div class="card-grid" id="grid-blog-posts"></div>
   221|    </div>
   222|
   223|    <!-- VIEWER: LinkedIn Posts -->
   224|    <div class="viewer" id="viewer-linkedin-posts">
   225|      <div class="search-bar"><span class="search-icon">🔍</span><input type="text" class="filter-input" data-viewer="linkedin-posts" placeholder="Search LinkedIn posts..."></div>
   226|      <div class="card-grid" id="grid-linkedin-posts"></div>
   227|    </div>
   228|
   229|  </div>
   230|</div>
   231|
   232|<!-- Modal -->
   233|<div class="modal-overlay" id="modalOverlay">
   234|  <div class="modal">
   235|    <h3 id="modalTitle">Confirm</h3>
   236|    <p id="modalDesc">Are you sure?</p>
   237|    <div class="modal-actions">
   238|      <button class="btn btn-cancel" id="modalCancel">Cancel</button>
   239|      <button class="btn btn-send" id="modalConfirm" style="background:var(--accent);color:#0f172a">Confirm</button>
   240|    </div>
   241|  </div>
   242|</div>
   243|
   244|<script>
   245|// ============================================================
   246|// DATA — Embedded from social-content-books.json (Books pipeline content)
   247|// All content items are loaded as JS objects directly in this script.
   248|// Sources: Books outreach messages, SaaS/Consulting nurture emails,
   249|//          X/Twitter posts, blog articles, and LinkedIn posts.
   250|// ============================================================
   251|
   252|// LinkedIn Outreach Messages
   253|const LINKEDIN_MSGS = [
   254|  {id:'lm1',target_type:'saas_hypatia',subject:'Scaling {{company}}\'s engineering velocity with AI-augmented pipelines',body:'Hi {{name}},\n\nI came across {{company}} while researching SaaS platforms pushing the boundaries of AI-native development. Your engineering team is clearly building at a high velocity.\n\nAt MIFECO, we\'ve developed Hypatia — an AI-augmented pipeline engine purpose-built for SaaS teams that need to ship faster without accumulating technical debt. It integrates directly into your existing CI/CD workflow, providing automated code review, intelligent test generation, and deployment risk scoring. Our early adopters report 40% faster release cycles and a 60% reduction in production incidents.\n\nUnlike generic DevOps tooling, Hypatia learns your team\'s specific codebase patterns and architectural preferences, becoming more valuable over time. It\'s designed for exactly the kind of high-performance engineering culture you\'re cultivating at {{company}}.\n\nWould you be open to a brief 15-minute call next week to explore whether Hypatia could help your team maintain velocity as you scale?\n\nBest,\nBob\nMIFECO',keywords:['AI pipeline engine','SaaS engineering velocity','automated code review','CI/CD optimization','AI DevOps tool','Hypatia pipeline']},
   255|  {id:'lm2',target_type:'saas_pma',subject:'Streamlining {{company}}\'s product-market alignment process',body:'Hi {{name}},\n\nI\'ve been impressed by {{company}}\'s trajectory in the SaaS space. As Head of Product, you know firsthand how challenging it is to maintain strong product-market alignment as you scale.\n\nThis is exactly why we built PMA at MIFECO — a Product-Market Alignment platform that helps product teams close the feedback loop between customer signals and roadmap decisions. It aggregates insights from support tickets, user interviews, NPS data, and usage analytics into a single prioritized view that connects directly to your product backlog.\n\nProduct leaders at scaling SaaS companies use PMA to cut feature waste by 35% and improve user adoption of new releases by 50%. Rather than relying on gut feel or fragmented data, you get a continuous, data-driven picture of what your market actually needs.\n\nI\'d love to show you how PMA works and discuss how it might fit {{company}}\'s product development rhythm. Could we schedule a 20-minute chat?\n\nBest,\nBob\nMIFECO',keywords:['product-market alignment','SaaS product management','customer feedback aggregation','roadmap prioritization','product analytics platform','PMA tool']},
   256|  {id:'lm3',target_type:'saas_vibra',subject:'Helping {{company}} improve user retention through behavioral AI',body:'Hi {{name}},\n\n{{company}} is building something exciting in the SaaS space, and I can see you\'re thoughtful about product decisions that drive real user engagement.\n\nAt MIFECO, we created Vibra — a behavioral AI platform that helps SaaS companies understand why users stay, churn, or expand. Vibra analyzes session data, feature usage patterns, and onboarding flows to identify the exact moments that predict long-term retention. It then surfaces actionable interventions your team can implement immediately.\n\nFounders and product leaders at growth-stage companies use Vibra to reduce churn by 25-40% within the first 90 days. Unlike traditional analytics tools that just show you what happened, Vibra tells you what to do about it and measures the impact of each change.\n\nI think {{company}} would find Vibra particularly valuable given your growth trajectory. Would you be open to a quick demo next week?\n\nBest,\nBob\nMIFECO',keywords:['user retention AI','behavioral analytics SaaS','churn reduction platform','SaaS user engagement','AI retention tool','Vibra behavioral AI']},
   257|  {id:'lm4',target_type:'consulting_199',subject:'A structured approach to {{company}}\'s next growth phase',body:'Hi {{name}},\n\nI\'ve been following {{company}} and I\'m genuinely impressed by what you\'re building. As a founder or leader at a growing company, I know your plate is full — every decision compounds.\n\nAt MIFECO, we offer a targeted $199 consulting engagement designed specifically for companies like {{company}}. Here\'s what it includes:\n\n1. A deep-dive analysis of your current operational and strategic landscape\n2. Prioritized recommendations for the highest-impact improvements\n3. A 30-day action plan with specific milestones\n4. A 60-minute strategy session to walk through everything\n\nThis isn\'t generic advice — it\'s a tailored engagement based on your specific market position, team structure, and growth goals. Past clients have used these sessions to identify critical bottlenecks, refine their go-to-market strategy, and unlock 20-30% efficiency gains.\n\nNo retainer, no long-term commitment — just actionable insights you can implement immediately.\n\nWould you be open to a brief call to see if this makes sense for {{company}}?\n\nBest,\nBob\nMIFECO',keywords:['consulting engagement','$199 strategy session','growth consulting','startup operations audit','business strategy consulting','affordable consulting']},
   258|  {id:'lm5',target_type:'consulting_dive',subject:'A deep operational dive for {{company}}\'s leadership team',body:'Hi {{name}},\n\n{{company}} is clearly operating at a high level — it takes real execution to achieve what you have in this market. At the same time, every scaling organization hits inflection points where a fresh external perspective can unlock the next level.\n\nOur Deep Dive consulting engagement at MIFECO is built for exactly this scenario. It\'s a comprehensive operational assessment that covers:\n\n• End-to-end process mapping and bottleneck identification\n• Organizational structure analysis and recommendations\n• Technology stack evaluation with concrete optimization suggestions\n• Competitive positioning review and market gap analysis\n• A fully documented strategic roadmap with 90-day priorities\n\nThe engagement runs 2-3 weeks and includes multiple stakeholder interviews, data analysis, and a formal presentation to your leadership team. It\'s the kind of thorough, actionable analysis that operational leaders at companies like {{company}} find transformative.\n\nI\'d love to walk you through how this has worked for similar organizations. Could we set up a 15-minute exploratory call?\n\nBest,\nBob\nMIFECO',keywords:['operational consulting','deep dive assessment','business operations strategy','organizational audit','process optimization consulting','strategic roadmap']},
   259|  {id:'lm6',target_type:'consulting_transform',subject:'Transforming {{company}}\'s operations for the next growth frontier',body:'Hi {{name}},\n\nI\'ve been watching {{company}}\'s journey — it\'s clear you\'re at an exciting inflection point. The companies that navigate these transitions best build scalable operational foundations before they absolutely need them.\n\nMIFECO\'s Transformation consulting is our flagship engagement: a full-spectrum operational overhaul covering strategic planning and OKR alignment, process reengineering with measurable efficiency targets, technology modernization including AI integration, team structure redesign, and change management to ensure adoption.\n\nOur clients typically see 50-80% higher operational throughput and 20-35% cost reduction while building the muscle to scale 3x without proportional headcount growth.\n\nFor a company like {{company}} with your trajectory, this could accelerate your entire growth plan. Are you open to a conversation about what this might look like for your team?\n\nBest,\nBob\nMIFECO',keywords:['business transformation consulting','operational overhaul','scale readiness consulting','AI transformation services','strategic operations consulting','MIFECO transformation']}
   260|];
   261|
   262|// Emails
   263|const EMAILS = [
   264|  // SaaS nurture (7)
   265|  {id:'em1',pipeline:'SaaS',day:1,subject:'Welcome to {{company}}! See LaunchPad in action',body:'Hi {{name}},\n\nThanks for requesting access to our LaunchPad SaaS platform preview! We\'re excited to show you how AI-powered automation can transform your service business.\n\nAt {{company}}, we build purpose-built SaaS solutions that help consultants, coaches, and agencies package their expertise into scalable products.\n\nLet\'s jump on a quick 15-minute demo to see LaunchPad in action:\n👉 [Schedule Your Demo](https://mife.co/demo)\n\nDuring the demo, you\'ll see:\n- How clients launch their own branded portals\n- Automated client onboarding & progress tracking\n- Built-in payment processing & subscription management\n- AI-powered content recommendations\n\nLooking forward to connecting,\nSales Director, {{company}}',cta:'Schedule Your Demo at https://mife.co/demo'},
