   502|let pendingAction = null;
   503|
   504|function confirmAction(viewer, id, action) {
   505|  const overlay = document.getElementById('modalOverlay');
   506|  const title = document.getElementById('modalTitle');
   507|  const desc = document.getElementById('modalDesc');
   508|  const confirm = document.getElementById('modalConfirm');
   509|  const type = viewer === 'linkedin-msgs' ? 'LinkedIn message' :
   510|    viewer === 'emails' ? 'email' :
   511|    viewer === 'x-posts' ? 'X post' :
   512|    viewer === 'blog-posts' ? 'blog post' : 'LinkedIn post';
   513|
   514|  if (action === 'send') {
   515|    title.textContent = 'Send this ' + type + '?';
   516|    desc.textContent = 'This will mark the item as sent and it will be visually confirmed.';
   517|    confirm.textContent = 'Send';
   518|    confirm.style.background = 'var(--accent)';
   519|    confirm.style.color = '#0f172a';
   520|  } else {
   521|    title.textContent = 'Remove this ' + type + ' from queue?';
   522|    desc.textContent = 'This will permanently remove the item with a slide-out animation.';
   523|    confirm.textContent = 'Delete';
   524|    confirm.style.background = 'var(--danger)';
   525|    confirm.style.color = '#fff';
   526|  }
   527|
   528|  pendingAction = { viewer, id, action };
   529|  overlay.classList.add('show');
   530|}
   531|
   532|document.getElementById('modalCancel').onclick = function() {
   533|  document.getElementById('modalOverlay').classList.remove('show');
   534|  pendingAction = null;
   535|};
   536|
   537|document.getElementById('modalConfirm').onclick = function() {
   538|  if (!pendingAction) return;
   539|  const { viewer, id, action } = pendingAction;
   540|  document.getElementById('modalOverlay').classList.remove('show');
   541|
   542|  if (action === 'send') {
   543|    markSent(id);
   544|    const card = document.querySelector(`.card[data-id="${id}"]`);
   545|    if (card) {
   546|      card.classList.add('sent');
   547|      const overlay = card.querySelector('.sent-overlay');
   548|      if (overlay) overlay.style.display = 'block';
   549|      const btn = card.querySelector('.btn-send');
   550|      if (btn) { btn.disabled = true; btn.textContent = '✓ Sent'; }
   551|    }
   552|  } else {
   553|    markDeleted(id);
   554|    const card = document.querySelector(`.card[data-id="${id}"]`);
   555|    if (card) {
   556|      card.classList.add('deleting');
   557|      setTimeout(() => {
   558|        if (card.parentNode) card.remove();
   559|        getAllItems(viewer);
   560|      }, 400);
   561|    }
   562|  }
   563|
   564|  updateAllBadges();
   565|  updateSidebarStats();
   566|  pendingAction = null;
   567|};
