   572|function countPending(viewer) {
   573|  const map = {
   574|    'linkedin-msgs': LINKEDIN_MSGS,
   575|    'emails': EMAILS,
   576|    'x-posts': X_POSTS,
   577|    'blog-posts': BLOG_POSTS,
   578|    'linkedin-posts': LINKEDIN_POSTS
   579|  };
   580|  const items = map[viewer] || [];
   581|  return items.filter(i => !isDeleted(i.id)).length;
   582|}
   583|
   584|function updateAllBadges() {
   585|  ['linkedin-msgs','emails','x-posts','blog-posts','linkedin-posts'].forEach(v => {
   586|    const badge = document.getElementById('badge-' + v);
   587|    if (badge) badge.textContent = countPending(v);
   588|  });
   589|}
   590|
   591|function updateSidebarStats() {
   592|  let total = 0, sent = 0, queued = 0;
   593|  [LINKEDIN_MSGS, EMAILS, X_POSTS, BLOG_POSTS, LINKEDIN_POSTS].forEach(arr => {
   594|    arr.forEach(i => {
   595|      if (!isDeleted(i.id)) {
   596|        total++;
   597|        if (isSent(i.id)) sent++; else queued++;
   598|      }
   599|    });
   600|  });
   601|  document.getElementById('statTotal').textContent = total;
   602|  document.getElementById('statSent').textContent = sent;
   603|  document.getElementById('statQueued').textContent = queued;
   604|}
