   606|function getAllItems(viewer) {
   607|  const filterInput = document.querySelector(`.filter-input[data-viewer="${viewer}"]`);
   608|  const filter = filterInput ? filterInput.value.toLowerCase() : '';
   609|
   610|  switch(viewer) {
   611|    case 'linkedin-msgs': renderLinkedInMsgs(LINKEDIN_MSGS, filter); break;
   612|    case 'emails': renderEmails(EMAILS, filter); break;
   613|    case 'x-posts': renderXPosts(X_POSTS, filter); break;
   614|    case 'blog-posts': renderBlogPosts(BLOG_POSTS, filter); break;
   615|    case 'linkedin-posts': renderLinkedInPosts(LINKEDIN_POSTS, filter); break;
   616|  }
