{"path": "~/.hermes/.openclaw/workspace/pipeline-engine/dashboard/content-command-center.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>MIFECO Content Command Center</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
<style>
:root {
  --bg: #0f172a;
  --card-bg: #1e293b;
  --accent: #00ffcc;
  --secondary: #667eea;
  --text: #e2e8f0;
  --text-muted: #94a3b8;
  --border: #334155;
  --danger: #ef4444;
  --success: #22c55e;
  --warning: #f59e0b;
  --approve: #f59e0b;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{font-size:16px}
body{font-family:'Inter',-apple-system,sans-serif;background:var(--bg);color:var(--text);display:flex;min-height:100vh;overflow-x:hidden}
a{color:var(--accent);text-decoration:none}
a:hover{text-decoration:underline}

/* Sidebar */
.sidebar{position:fixed;left:0;top:0;bottom:0;width:220px;background:#0c1225;border-right:1px solid var(--border);display:flex;flex-direction:column;z-index:100;transition:transform .3s ease}
.sidebar-logo{padding:24px 20px 16px;border-bottom:1px solid var(--border)}
.sidebar-logo .logo-icon{width:36px;height:36px;background:var(--accent);border-radius:8px;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:18px;color:#0f172a;margin-bottom:8px}
.sidebar-logo h2{font-size:15px;font-weight:700;color:var(--text);letter-spacing:-.3px}
.sidebar-logo p{font-size:10px;color:var(--accent);text-transform:uppercase;letter-spacing:1.5px;font-weight:600;margin-top:2px}
.sidebar-stats{padding:20px;border-bottom:1px solid var(--border);display:flex;flex-direction:column;gap:12px}
.stat-item{display:flex;justify-content:space-between;align-items:center}
.stat-label{font-size:12px;color:var(--text-muted)}
.stat-value{font-size:16px;font-weight:700;color:var(--text)}
.stat-value.accent{color:var(--accent)}
.stat-value.success{color:var(--success)}
.stat-value.secondary{color:var(--secondary)}
.stat-value.approved{color:var(--approve)}
.sidebar-nav{padding:16px 0;flex:1}
.sidebar-nav a{display:flex;align-items:center;gap:10px;padding:10px 20px;font-size:13px;color:var(--text-muted);transition:all .15s}
.sidebar-nav a:hover{color:var(--text);background:rgba(255,255,255,.04);text-decoration:none}
.sidebar-nav a .nav-icon{width:18px;text-align:center;font-size:15px}
.sidebar-nav a.active{color:var(--accent);border-left:2px solid var(--accent);background:rgba(0,255,204,.06)}

/* Main */
.main{padding-left:220px;width:100%;min-height:100vh;display:flex;flex-direction:column}

/* Header */
.header{padding:24px 32px 16px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:flex-start}
.header-left h1{font-size:22px;font-weight:800;letter-spacing:-.5px;color:var(--text)}
.header-left p{font-size:13px;color:var(--text-muted);margin-top:4px}
.header-right{display:flex;gap:12px;align-items:center}
.hamburger{display:none;background:none;border:none;color:var(--text);font-size:24px;cursor:pointer;padding:4px}
.mobile-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:99}

/* Tabs */
.tabs{display:flex;border-bottom:1px solid var(--border);padding:0 32px;overflow-x:auto;scrollbar-width:none;gap:0}
.tabs::-webkit-scrollbar{display:none}
.tab-btn{background:none;border:none;color:var(--text-muted);padding:14px 20px;font-size:13px;font-weight:500;cursor:pointer;position:relative;white-space:nowrap;transition:color .15s;font-family:'Inter',sans-serif}
.tab-btn:hover{color:var(--text)}
.tab-btn.active{color:var(--accent)}
.tab-btn.active::after{content:'';position:absolute;bottom:0;left:8px;right:8px;height:2px;background:var(--accent);border-radius:2px}
.tab-badge{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 5px;border-radius:9px;background:var(--secondary);color:#fff;font-size:10px;font-weight:700;margin-left:6px;vertical-align:middle}

/* Content */
.content-area{flex:1;padding:24px 32px}
.viewer{display:none}
.viewer.active{display:block}

/* Search */
.search-bar{position:relative;margin-bottom:20px}
.search-bar input{width:100%;padding:10px 16px 10px 40px;background:var(--card-bg);border:1px solid var(--border);border-radius:8px;color:var(--text);font-size:13px;font-family:'Inter',sans-serif;outline:none;transition:border .15s}
.search-bar input:focus{border-color:var(--accent)}
.search-bar input::placeholder{color:var(--text-muted)}
.search-bar .search-icon{position:absolute;left:14px;top:50%;transform:translateY(-50%);color:var(--text-muted);font-size:15px;pointer-events:none}

/* Cards */
.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:16px}
.card{background:var(--card-bg);border:1px solid var(--border);border-radius:10px;padding:18px;transition:all .3s ease;position:relative;overflow:hidden}
.card.sent{border-color:var(--success) !important;background:rgba(34,197,94,.04)}
.card.approved{border-color:var(--approve) !important;background:rgba(245,158,11,.04)}
.card.deleting{transform:translateX(120%);opacity:0;max-height:0;padding:0;margin:0;border-width:0;overflow:hidden;transition:all .4s ease}
.card .sent-overlay{display:none;position:absolute;top:8px;right:8px;background:var(--success);color:#fff;font-size:10px;font-weight:700;padding:3px 8px;border-radius:4px;letter-spacing:.3px}
.card.sent .sent-overlay{display:block}
.card .approved-overlay{display:none;position:absolute;top:8px;right:8px;background:var(--approve);color:#fff;font-size:10px;font-weight:700;padding:3px 8px;border-radius:4px;letter-spacing:.3px}
.card.approved .approved-overlay{display:block}
.card .badge{display:inline-block;font-size:10px;font-weight:600;padding:3px 8px;border-radius:4px;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px}
.badge-saas{background:rgba(102,126,234,.2);color:var(--secondary)}
.badge-consulting{background:rgba(245,158,11,.2);color:var(--warning)}
.badge-books{background:rgba(0,255,204,.15);color:var(--accent)}
.badge-testcorp{background:rgba(239,68,68,.15);color:var(--danger)}
.badge-hypatia{background:rgba(102,126,234,.2);color:var(--secondary)}
.badge-pma{background:rgba(0,255,204,.15);color:var(--accent)}
.badge-vibra{background:rgba(245,158,11,.2);color:var(--warning)}
.badge-consult{background:rgba(239,68,68,.15);color:var(--danger)}
.badge-linkedin{background:rgba(10,102,194,.2);color:#0a66c2}
.badge-x{background:rgba(0,0,0,.3);color:#e2e8f0}
.card h3{font-size:14px;font-weight:600;color:var(--text);line-height:1.4;margin-bottom:6px}
.card .meta{font-size:11px;color:var(--text-muted);margin-bottom:8px;display:flex;flex-wrap:wrap;gap:6px}
.card .body-preview{font-size:12.5px;color:var(--text-muted);line-height:1.6;margin-bottom:10px;max-height:72px;overflow:hidden;transition:max-height .3s ease;position:relative}
.card .body-preview.expanded{max-height:2000px}
.card .body-preview .placeholder{background:rgba(0,255,204,.1);color:var(--accent);padding:1px 4px;border-radius:3px;font-weight:500;font-size:11px}
.card .expand-btn{background:none;border:none;color:var(--accent);font-size:11px;cursor:pointer;padding:0;font-family:'Inter',sans-serif;font-weight:500}
.card .expand-btn:hover{text-decoration:underline}
.card .keywords{display:flex;flex-wrap:wrap;gap:4px;margin-bottom:12px}
.card .keyword{font-size:10px;background:rgba(102,126,234,.1);color:var(--secondary);padding:2px 6px;border-radius:3px}
.card .actions{display:flex;gap:8px;margin-top:0;flex-wrap:wrap}
.btn{font-family:'Inter',sans-serif;font-size:12px;font-weight:600;padding:7px 16px;border-radius:6px;border:none;cursor:pointer;transition:all .15s;display:inline-flex;align-items:center;gap:5px}
.btn-send{background:var(--accent);color:#0f172a}
.btn-send:hover{background:#00e6b8;transform:translateY(-1px)}
.btn-send:disabled{opacity:.4;cursor:not-allowed;transform:none}
.btn-approve{background:var(--approve);color:#0f172a}
.btn-approve:hover{background:#e0900a;transform:translateY(-1px)}
.btn-approve:disabled{opacity:.4;cursor:not-allowed;transform:none}
.btn-approve.approved-done{background:transparent;border:1px solid var(--approve);color:var(--approve);cursor:default}
.btn-view{background:transparent;border:1px solid var(--secondary);color:var(--secondary)}
.btn-view:hover{background:var(--secondary);color:#fff}
.btn-delete{background:transparent;border:1px solid var(--danger);color:var(--danger)}
.btn-delete:hover{background:var(--danger);color:#fff}
.btn-cancel{background:var(--border);color:var(--text)}
.btn-cancel:hover{background:#3b4f6b}

/* Modal */
.modal-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:200;align-items:center;justify-content:center}
.modal-overlay.show{display:flex}
.modal{background:var(--card-bg);border:1px solid var(--border);border-radius:12px;padding:28px;max-width:480px;width:90%;text-align:center}
.modal h3{font-size:17px;font-weight:700;margin-bottom:8px}
.modal p{font-size:13px;color:var(--text-muted);margin-bottom:20px;line-height:1.5}
.modal .modal-actions{display:flex;gap:10px;justify-content:center}

/* View Modal */
.view-modal-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.85);z-index:300;align-items:flex-start;justify-content:center;padding:40px 20px;overflow-y:auto}
.view-modal-overlay.show{display:flex}
.view-modal{background:var(--card-bg);border:1px solid var(--border);border-radius:12px;max-width:720px;width:100%;padding:32px;position:relative;margin:auto 0}
.view-modal .close-btn{position:absolute;top:16px;right:16px;background:transparent;border:1px solid var(--border);color:var(--text-muted);width:32px;height:32px;border-radius:6px;cursor:pointer;font-size:16px;display:flex;align-items:center;justify-content:center;transition:all .15s}
.view-modal .close-btn:hover{background:var(--danger);color:#fff;border-color:var(--danger)}
.view-modal .vm-header{margin-bottom:20px;padding-bottom:16px;border-bottom:1px solid var(--border)}
.view-modal .vm-subject{font-size:18px;font-weight:700;color:var(--text);line-height:1.3;margin-bottom:4px}
.view-modal .vm-meta{font-size:12px;color:var(--text-muted);display:flex;gap:12px;flex-wrap:wrap}
.view-modal .vm-meta span{display:flex;align-items:center;gap:4px}
.view-modal .vm-body{font-size:14px;color:var(--text);line-height:1.8;white-space:pre-wrap;word-break:break-word}
.view-modal .vm-body .placeholder{background:rgba(0,255,204,.1);color:var(--accent);padding:1px 4px;border-radius:3px;font-weight:500;font-size:12px}
.view-modal .vm-keywords{display:flex;flex-wrap:wrap;gap:6px;margin-top:20px;padding-top:16px;border-top:1px solid var(--border)}
.view-modal .vm-keywords .kw{font-size:11px;background:rgba(102,126,234,.1);color:var(--secondary);padding:3px 8px;border-radius:4px}
.view-modal .vm-footer{display:flex;gap:10px;margin-top:20px;padding-top:16px;border-top:1px solid var(--border);justify-content:flex-end}
.view-modal .vm-status{font-size:12px;color:var(--text-muted);margin-bottom:12px;display:flex;gap:12px;flex-wrap:wrap}
.view-modal .vm-status .status-badge{padding:3px 10px;border-radius:4px;font-weight:600;font-size:11px}
.view-modal .vm-status .status-badge.pending{background:rgba(148,163,184,.15);color:var(--text-muted)}
.view-modal .vm-status .status-badge.approved{background:rgba(245,158,11,.2);color:var(--approve)}
.view-modal .vm-status .status-badge.sent{background:rgba(34,197,94,.2);color:var(--success)}

/* Empty state */
.empty-state{text-align:center;padding:60px 20px;color:var(--text-muted)}
.empty-state .empty-icon{font-size:48px;margin-bottom:12px;opacity:.5}
.empty-state h3{font-size:16px;color:var(--text);margin-bottom:6px}
.empty-state p{font-size:13px;max-width:400px;margin:0 auto;line-height:1.6}

/* Responsive */
@media(max-width:768px){
  .sidebar{transform:translateX(-100%)}
  .sidebar.open{transform:translateX(0)}
  .mobile-overlay.show{display:block}
  .main{padding-left:0}
  .header{padding:16px;flex-direction:column;gap:8px}
  .header-right{width:100%;justify-content:flex-start}
  .hamburger{display:block}
  .tabs{padding:0 12px}
  .tab-btn{padding:12px 14px;font-size:12px}
  .content-area{padding:16px}
  .card-grid{grid-template-columns:1fr}
  .view-modal{padding:20px}
  .view-modal .vm-subject{font-size:16px}
  .view-modal .vm-body{font-size:13px}
}
@media(max-width:480px){
  .card-grid{grid-template-columns:1fr}
}
</style>
</head>
<body>

<div class="mobile-overlay" id="mobileOverlay"></div>

<!-- Sidebar -->
<aside class="sidebar" id="sidebar">
