    <p>Command Center</p>
  </div>
  <div class="sidebar-stats">
    <div class="stat-item"><span class="stat-label">Total Items</span><span class="stat-value" id="statTotal">0</span></div>
    <div class="stat-item"><span class="stat-label">Approved</span><span class="stat-value approved" id="statApproved">0</span></div>
    <div class="stat-item"><span class="stat-label">Sent</span><span class="stat-value success" id="statSent">0</span></div>
    <div class="stat-item"><span class="stat-label">Queued</span><span class="stat-value accent" id="statQueued">0</span></div>
  </div>
  <nav class="sidebar-nav">
