    <a href="pipeline-dashboard.html"><span class="nav-icon">🔁</span> Pipeline Dashboard</a>
  </nav>
</aside>

<!-- Main -->
<div class="main">

  <!-- Header -->
  <header class="header">
    <div class="header-left">
      <button class="hamburger" id="hamburger">☰</button>
      <h1>MIFECO Content Command Center</h1>
      <p>Review, approve, and deploy content across all channels — nothing sends until you approve it</p>
    </div>
    <div class="header-right">
      <span style="font-size:12px;color:var(--text-muted)">v2.0 · Approval Required</span>
    </div>
  </header>

  <!-- Tabs -->
  <nav class="tabs" id="tabNav">
    <button class="tab-btn active" data-tab="linkedin-msgs">LinkedIn Messages <span class="tab-badge" id="badge-linkedin-msgs">0</span></button>
    <button class="tab-btn" data-tab="emails">Emails <span class="tab-badge" id="badge-emails">0</span></button>
