// ============================================================
// STATE MANAGEMENT
// ============================================================
const LS_KEY = 'mifeco_content_center_v2';

function loadState() {
  try {
    const raw = localStorage.getItem(LS_KEY);
    return raw ? JSON.parse(raw) : { approved: {}, sent: {}, deleted: {} };
  } catch(e) { return { approved: {}, sent: {}, deleted: {} }; }
}

function saveState(st) { localStorage.setItem(LS_KEY, JSON.stringify(st)); }

let state = loadState();

function isApproved(id) { return state.approved[id] === true; }
function isSent(id) { return state.sent[id] === true; }
function isDeleted(id) { return state.deleted[id] === true; }
function markApproved(id) { state.approved[id] = true; saveState(state); }
function markSent(id) { state.sent[id] = true; saveState(state); }
function markDeleted(id) { state.deleted[id] = true; saveState(state); }

// ============================================================
// RENDER ENGINE
// ============================================================

function escapeHtml(t) { return t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;'); }

function highlightPlaceholders(text) {
  return escapeHtml(text).replace(/\{\{(\w+)\}\}/g, '<span class="placeholder">{{$1}}</span>');
}

function truncateBody(text, maxLen=200) {
  if (text.length <= maxLen) return { preview: highlightPlaceholders(text), needsExpand: false };
  return { preview: highlightPlaceholders(text.slice(0, maxLen)) + '...', needsExpand: true };
}

function badgeClass(key) {
  const map = {
    'saas_hypatia':'badge-hypatia','saas_pma':'badge-pma','saas_vibra':'badge-vibra',
    'consulting_199':'badge-consult','consulting_dive':'badge-consult','consulting_transform':'badge-consult'
  };
  return map[key] || 'badge-consulting';
}

function pipelineBadge(p) {
  if (p === 'SaaS') return 'badge-saas';
  if (p === 'Consulting') return 'badge-consulting';
  if (p === 'Books') return 'badge-books';
  if (p === 'TestCorp') return 'badge-testcorp';
  return 'badge-consulting';
}

function getItemType(viewer) {
  return viewer === 'linkedin-msgs' ? 'LinkedIn Message' :
    viewer === 'emails' ? 'Email' :
    viewer === 'x-posts' ? 'X Post' :
    viewer === 'blog-posts' ? 'Blog Post' : 'LinkedIn Post';
}

function getItem(viewer, id) {
  const map = {
    'linkedin-msgs': LINKEDIN_MSGS,
    'emails': EMAILS,
    'x-posts': X_POSTS,
    'blog-posts': BLOG_POSTS,
    'linkedin-posts': LINKEDIN_POSTS
  };
  return (map[viewer] || []).find(i => i.id === id);
}

function getItemViews(viewer) {
  return { pending: 0, approved: 0, sent: 0 };
}

function buildCardActions(viewer, id, item) {
  const approved = isApproved(id);
  const sent = isSent(id);
  const type = getItemType(viewer);
  const lowerType = type.toLowerCase();

  // View button — always visible
  let html = `<button class="btn btn-view" onclick="openViewModal('${viewer}','${id}')">👁 View</button>`;

  if (sent) {
    // Sent state: show only status
    html += `<button class="btn btn-send" disabled>✓ Sent</button>`;
    return html;
  }

  if (approved) {
    // Approved but not yet sent: show Send + Delete
    html += `<button class="btn btn-approve approved-done">✔ Approved</button>`;
    html += `<button class="btn btn-send" onclick="confirmAction('${viewer}','${id}','send')">📤 Send Now</button>`;
    html += `<button class="btn btn-delete" onclick="confirmAction('${viewer}','${id}','delete')">🗑 Delete</button>`;
  } else {
    // Pending: show Approve + Delete
    html += `<button class="btn btn-approve" onclick="confirmAction('${viewer}','${id}','approve')">✔ Approve</button>`;
    html += `<button class="btn btn-delete" onclick="confirmAction('${viewer}','${id}','delete')">🗑 Delete</button>`;
  }

  return html;
}

function renderLinkedInMsgs(items, filter='') {
  const grid = document.getElementById('grid-linkedin-msgs');
  const filtered = items.filter(i => !isDeleted(i.id) && (!filter || i.subject.toLowerCase().includes(filter) || i.body.toLowerCase().includes(filter)));
  if (filtered.length === 0) { grid.innerHTML = '<div class="empty-state"><div class="empty-icon">📬</div><h3>No LinkedIn Messages</h3><p>All messages have been processed or none match your search.</p></div>'; return; }
  grid.innerHTML = filtered.map(item => {
    const sent = isSent(item.id);
    const approved = isApproved(item.id);
    const bodyInfo = truncateBody(item.body);
    let extraClass = '';
    if (sent) extraClass = ' sent';
    else if (approved) extraClass = ' approved';
    return `<div class="card${extraClass}" data-id="${item.id}">
      ${sent?'<div class="sent-overlay">✓ Sent</div>':(approved?'<div class="approved-overlay">✔ Approved</div>':'')}
      <span class="badge ${badgeClass(item.target_type)}">${item.target_type}</span>
      <h3>${escapeHtml(item.subject)}</h3>
      <div class="meta">LinkedIn Outreach · ${item.keywords ? item.keywords[0] : ''}</div>
      <div class="body-preview${bodyInfo.needsExpand?'':' expanded'}" data-expanded="${bodyInfo.needsExpand?'false':'true'}">${bodyInfo.preview}</div>
      ${bodyInfo.needsExpand?`<button class="expand-btn" onclick="toggleExpand(this)">Show more</button>`:''}
      ${item.keywords ? `<div class="keywords">${item.keywords.map(k=>`<span class="keyword">${escapeHtml(k)}</span>`).join('')}</div>` : ''}
      <div class="actions">${buildCardActions('linkedin-msgs', item.id, item)}</div>
    </div>`;
  }).join('');
}

