      <div style="font-size:10px;color:var(--text-muted);margin:6px 0 8px;padding:6px;background:rgba(0,0,0,.2);border-radius:4px"><em>🎨 ${escapeHtml(item.graphic_prompt.slice(0,80))}...</em></div>
      <div class="actions">${buildCardActions('linkedin-posts', item.id, item)}</div>
    </div>`;
  }).join('');
}

function toggleExpand(btn) {
  const preview = btn.previousElementSibling;
  const isExpanded = preview.style.maxHeight === '2000px' || preview.classList.contains('expanded');
  preview.style.maxHeight = isExpanded ? '72px' : '2000px';
  preview.classList.toggle('expanded');
  btn.textContent = isExpanded ? 'Show more' : 'Show less';
}

// ============================================================
// VIEW MODAL — Full content viewer
// ============================================================
let currentViewItem = null;
let currentViewViewer = null;

function openViewModal(viewer, id) {
  const item = getItem(viewer, id);
  if (!item) return;

  currentViewItem = item;
  currentViewViewer = viewer;

  const type = getItemType(viewer);
  const sent = isSent(id);
  const approved = isApproved(id);

  let statusHtml = '';
  if (sent) statusHtml = '<span class="status-badge sent">✓ Sent</span>';
  else if (approved) statusHtml = '<span class="status-badge approved">✔ Approved</span>';
  else statusHtml = '<span class="status-badge pending">⏳ Pending Approval</span>';
  statusHtml += `<span class="status-badge" style="background:rgba(102,126,234,.2);color:var(--secondary)">${escapeHtml(type)}</span>`;

  // Get metadata
  let metaHtml = `<span>📌 ${escapeHtml(type)}</span>`;
  if (item.pipeline) metaHtml += `<span>📋 ${escapeHtml(item.pipeline)}</span>`;
  if (item.day) metaHtml += `<span>📆 Day ${item.day}</span>`;
  if (item.target_type) metaHtml += `<span>🎯 ${escapeHtml(item.target_type)}</span>`;
  if (item.book) metaHtml += `<span>📖 ${escapeHtml(item.book)}</span>`;
  if (item.publish_date) metaHtml += `<span>📅 ${item.publish_date}</span>`;
  if (item.cta) metaHtml += `<span>🔗 ${escapeHtml(item.cta)}</span>`;
  if (item.graphic_prompt) metaHtml += `<span>🎨 ${escapeHtml(item.graphic_prompt.slice(0,100))}...</span>`;

  document.getElementById('vmSubject').textContent = item.subject || item.title || item.book || '(Untitled)';

  // Show full subject for items that have it
  if (item.subject) {
    document.getElementById('vmSubject').textContent = item.subject;
  } else if (item.title) {
    document.getElementById('vmSubject').textContent = item.title;
  } else if (item.book) {
    document.getElementById('vmSubject').textContent = item.book + ' — ' + type;
  }

  document.getElementById('vmMeta').innerHTML = metaHtml;
  document.getElementById('vmStatus').innerHTML = statusHtml;

  // Body — highlight placeholders
  const bodyText = item.body || item.copy || '';
  document.getElementById('vmBody').innerHTML = highlightPlaceholders(bodyText);

  // Keywords
  const kwEl = document.getElementById('vmKeywords');
  const kw = item.keywords || (item.hashtags ? item.hashtags.split(' ').slice(0,10) : []);
  if (kw.length > 0) {
    kwEl.innerHTML = kw.map(k => `<span class="kw">${escapeHtml(typeof k === 'string' ? k : k)}</span>`).join('');
    kwEl.style.display = 'flex';
  } else {
    kwEl.style.display = 'none';
  }

  // Footer buttons — match current state
  const approveBtn = document.getElementById('vmApproveBtn');
  const sendBtn = document.getElementById('vmSendBtn');
  const deleteBtn = document.getElementById('vmDeleteBtn');

  if (sent) {
    approveBtn.style.display = 'none';
    sendBtn.style.display = 'none';
    deleteBtn.style.display = 'none';
  } else if (approved) {
    approveBtn.style.display = 'none';
    sendBtn.style.display = 'inline-flex';
    deleteBtn.style.display = 'inline-flex';
    sendBtn.onclick = function() { closeViewModal(); confirmAction(viewer, id, 'send'); };
  } else {
    approveBtn.style.display = 'inline-flex';
    sendBtn.style.display = 'none';
    deleteBtn.style.display = 'inline-flex';
    approveBtn.onclick = function() { closeViewModal(); confirmAction(viewer, id, 'approve'); };
  }
  deleteBtn.onclick = function() { closeViewModal(); confirmAction(viewer, id, 'delete'); };

  document.getElementById('viewModalOverlay').classList.add('show');
  document.body.style.overflow = 'hidden';
}

function closeViewModal() {
  document.getElementById('viewModalOverlay').classList.remove('show');
  document.body.style.overflow = '';
  currentViewItem = null;
  currentViewViewer = null;
}

document.getElementById('viewModalClose').onclick = closeViewModal;
document.getElementById('vmCloseBtn').onclick = closeViewModal;
document.getElementById('viewModalOverlay').onclick = function(e) {
  if (e.target === this) closeViewModal();
};

// ============================================================
// CONFIRMATION MODAL
// ============================================================
let pendingAction = null;

function confirmAction(viewer, id, action) {
  const overlay = document.getElementById('modalOverlay');
  const title = document.getElementById('modalTitle');
  const desc = document.getElementById('modalDesc');
  const confirm = document.getElementById('modalConfirm');
  const type = getItemType(viewer);

  if (action === 'approve') {
    title.textContent = 'Approve this ' + type + '?';
    desc.textContent = 'You are approving this content for publication. Once approved, the Send button will become active. Nothing will be sent yet — this just grants permission.';
    confirm.textContent = '✔ Approve';
    confirm.style.background = 'var(--approve)';
    confirm.style.color = '#0f172a';
  } else if (action === 'send') {
    title.textContent = 'Send this ' + type + ' now?';
    desc.textContent = 'This content has been approved. Clicking Send will dispatch it to the webhook for delivery. This action cannot be undone.';
    confirm.textContent = '📤 Send Now';
    confirm.style.background = 'var(--accent)';
    confirm.style.color = '#0f172a';
  } else {
    title.textContent = 'Remove this ' + type + ' from queue?';
    desc.textContent = 'This will permanently remove the item with a slide-out animation.';
    confirm.textContent = '🗑 Delete';
    confirm.style.background = 'var(--danger)';
    confirm.style.color = '#fff';
  }

  pendingAction = { viewer, id, action };
  overlay.classList.add('show');
}

document.getElementById('modalCancel').onclick = function() {
  document.getElementById('modalOverlay').classList.remove('show');
  pendingAction = null;
};

document.getElementById('modalConfirm').onclick = function() {
  if (!pendingAction) return;
  const { viewer, id, action } = pendingAction;
  document.getElementById('modalOverlay').classList.remove('show');

  if (action === 'approve') {
    markApproved(id);
    // Update card UI
    const card = document.querySelector(`.card[data-id="${id}"]`);
    if (card) {
      card.classList.remove('approved');
      // Force reflow
      void card.offsetWidth;
      card.classList.add('approved');
      // Replace actions: remove approve, add send
      const actionsEl = card.querySelector('.actions');
      if (actionsEl) {
        actionsEl.innerHTML = buildCardActions(viewer, id, getItem(viewer, id));
      }
      // Add overlay
      const oldOverlay = card.querySelector('.approved-overlay');
      if (!oldOverlay) {
        const ao = document.createElement('div');
        ao.className = 'approved-overlay';
        ao.textContent = '✔ Approved';
        card.appendChild(ao);
      }
      const sentOverlay = card.querySelector('.sent-overlay');
      if (sentOverlay) sentOverlay.style.display = 'none';
    }
  } else if (action === 'send') {
    markSent(id);
    const card = document.querySelector(`.card[data-id="${id}"]`);
    if (card) {
      card.classList.remove('approved');
      card.classList.add('sent');
      const actionsEl = card.querySelector('.actions');
      if (actionsEl) {
        actionsEl.innerHTML = buildCardActions(viewer, id, getItem(viewer, id));
      }
      // Replace overlays
      const approvedOverlay = card.querySelector('.approved-overlay');
      if (approvedOverlay) approvedOverlay.style.display = 'none';
      const sentOverlay = card.querySelector('.sent-overlay');
      if (sentOverlay) sentOverlay.style.display = 'block';
      else {
        const so = document.createElement('div');
        so.className = 'sent-overlay';
        so.textContent = '✓ Sent';
        card.appendChild(so);
      }
    }
    // Send webhook notification
    notifyWebhook(viewer, id, 'sent');
  } else if (action === 'delete') {
    markDeleted(id);
    const card = document.querySelector(`.card[data-id="${id}"]`);
    if (card) {
      card.classList.add('deleting');
      setTimeout(() => {
        if (card.parentNode) card.remove();
        getAllItems(viewer);
      }, 400);
    }
    notifyWebhook(viewer, id, 'deleted');
  }

  updateAllBadges();
  updateSidebarStats();
  pendingAction = null;
};

// ============================================================
// WEBHOOK NOTIFICATION
// ============================================================
function notifyWebhook(viewer, id, action) {
  const item = getItem(viewer, id);
  if (!item) return;

  const payload = {
    secret: 'Rm2214ri%%%%',
    action: 'content_action',
    content: {
      viewer: viewer,
      item_id: id,
      action: action,
      type: getItemType(viewer),
      timestamp: new Date().toISOString()
    }
  };

  // Fire-and-forget POST to webhook
  fetch('/admin/webhook.php', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  }).catch(function(e) {
    console.log('Webhook notify (non-critical):', e);
  });
}

// ============================================================
// ITEM COUNTS & STATS
// ============================================================
function countPending(viewer) {
  const map = {
    'linkedin-msgs': LINKEDIN_MSGS,
    'emails': EMAILS,
    'x-posts': X_POSTS,
    'blog-posts': BLOG_POSTS,
    'linkedin-posts': LINKEDIN_POSTS
  };
  const items = map[viewer] || [];
  return items.filter(i => !isDeleted(i.id)).length;
}

function updateAllBadges() {
  ['linkedin-msgs','emails','x-posts','blog-posts','linkedin-posts'].forEach(v => {
    const badgeEl = document.getElementById('badge-' + v);
    if (badgeEl) badgeEl.textContent = countPending(v);
  });
}

function updateSidebarStats() {
  let total = 0, approved = 0, sent = 0, queued = 0;
  [LINKEDIN_MSGS, EMAILS, X_POSTS, BLOG_POSTS, LINKEDIN_POSTS].forEach(arr => {
    arr.forEach(i => {
      if (!isDeleted(i.id)) {
        total++;
        if (isSent(i.id)) sent++;
        else if (isApproved(i.id)) approved++;
        else queued++;
      }
    });
  });
  document.getElementById('statTotal').textContent = total;
  document.getElementById('statApproved').textContent = approved;
  document.getElementById('statSent').textContent = sent;
  document.getElementById('statQueued').textContent = queued;
}

function getAllItems(viewer) {
  const filterInput = document.querySelector(`.filter-input[data-viewer="${viewer}"]`);
  const filter = filterInput ? filterInput.value.toLowerCase() : '';

  switch(viewer) {
    case 'linkedin-msgs': renderLinkedInMsgs(LINKEDIN_MSGS, filter); break;
    case 'emails': renderEmails(EMAILS, filter); break;
    case 'x-posts': renderXPosts(X_POSTS, filter); break;
    case 'blog-posts': renderBlogPosts(BLOG_POSTS, filter); break;
    case 'linkedin-posts': renderLinkedInPosts(LINKEDIN_POSTS, filter); break;
  }
}

// ============================================================
// TABS
// ============================================================
document.querySelectorAll('.tab-btn').forEach(btn => {
  btn.addEventListener('click', function() {
    document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
    this.classList.add('active');
    document.querySelectorAll('.viewer').forEach(v => v.classList.remove('active'));
    const tab = this.dataset.tab;
    document.getElementById('viewer-' + tab).classList.add('active');
    getAllItems(tab);
  });
});

// Search
document.querySelectorAll('.filter-input').forEach(inp => {
  inp.addEventListener('input', function() {
    const viewer = this.dataset.viewer;
    getAllItems(viewer);
  });
});

// Sidebar toggle (mobile)
document.getElementById('hamburger').onclick = function() {
  document.getElementById('sidebar').classList.toggle('open');
  document.getElementById('mobileOverlay').classList.toggle('show');
};
document.getElementById('mobileOverlay').onclick = function() {
  document.getElementById('sidebar').classList.remove('open');
  this.classList.remove('show');
};

// ============================================================
// KEYBOARD SHORTCUT
// ============================================================
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    const viewModal = document.getElementById('viewModalOverlay');
    if (viewModal.classList.contains('show')) {
      closeViewModal();
      e.preventDefault();
    }
    const confirmModal = document.getElementById('modalOverlay');
    if (confirmModal.classList.contains('show')) {
      confirmModal.classList.remove('show');
      pendingAction = null;
    }
  }
});

// ============================================================
// INIT
// ============================================================
function init() {
  // Render all viewers
  renderLinkedInMsgs(LINKEDIN_MSGS);
  renderEmails(EMAILS);
  renderXPosts(X_POSTS);
  renderBlogPosts(BLOG_POSTS);
  renderLinkedInPosts(LINKEDIN_POSTS);
  updateAllBadges();
  updateSidebarStats();
}

init();
</script>
</body>
</html>
"}

